def describe(name, age=0, *hobbies, **extra):
    print(name, age, hobbies, extra)

describe("Asha", 21, "chess", "reading", city="Pune")
# Asha 21 ('chess', 'reading') {'city': 'Pune'}

def min_max(numbers):
    return min(numbers), max(numbers)

lo, hi = min_max([4, 1, 9, 2])
print(lo, hi)   # 1 9
